class Solution {
public:
    int pathSum(TreeNode* root, int targetSum) {
        unordered_map<long long, int> seen;
        seen[0] = 1;
        int count = 0;
        dfs(root, 0LL, targetSum, seen, count);
        return count;
    }
private:
    void dfs(TreeNode* node, long long sum, int targetSum,
             unordered_map<long long, int>& seen, int& count) {
        if (!node) return;
        sum += node->val;
        count += seen[sum - targetSum];
        seen[sum]++;
        dfs(node->left, sum, targetSum, seen, count);
        dfs(node->right, sum, targetSum, seen, count);
        seen[sum]--;
    }
};
